            "kept": sorted({(r["policy"], r["cap"], r["word"]) for r, h in zip(rows, hits) if not h}, key=str)}

def framework_bonds(campaign):
    """The Framework's sieve over the same raw rows, read from the built companion (cross-check)."""
    sys.path.insert(0, str(GEN))
    from constraints import sieve as sv
    sidecar = json.loads((HERE / "spec" / campaign / "demo.constraints.json").read_text())

    def bonds(_c, r):
        row = []
        if r["cap"] is not None:
            row.append({"sheet": "CAP", "value": f"cap({r['cap']});", "pos": 0})
        row += [{"sheet": f"S{i}", "value": f'set_step({i},"{t}");', "pos": i} for i, t in enumerate(r["word"], start=1)]
        return sv.row_violations(row, sidecar)
    return bonds

def precheck(campaign):
    rep = {"schema": "d6.precheck/v1", "campaign": campaign, "note": "before execution; independent of the SUT and runtime"}
    ws = words(campaign)
    if campaign == "counter":
        rep["words"] = {w: {"two_each": two_each(w), "prefix_preemptions": prefix_preemptions(w), "expression": expression(w),
                            "context_switches": switches(w)} for w in ws}
        rep["expression_equals_prefix_count_on_all_16"] = all(v["prefix_preemptions"] == v["expression"] for v in rep["words"].values())
        rep["schedules_by_cap"] = {c: sorted(w for w in ws if two_each(w) and prefix_preemptions(w) <= c) for c in (0, 1, 2)}
    else:
        rep["words"] = {w: dict(zip(("status", "detail"), explore_queue(w))) for w in ws}
        feasible = sorted(w for w, v in rep["words"].items() if v["status"] == "feasible")
        rep["feasible"] = feasible
        rep["infeasible_two_each"] = {w: v["detail"] for w, v in rep["words"].items() if v["status"] == "disabled"}
        rep["feasible_equals_first_letter_P"] = feasible == sorted(w for w in ws if two_each(w) and w[0] == "P")
    own = truth_table(campaign, own_bonds)
    fw = truth_table(campaign, framework_bonds(campaign))
    rep["truth_table"] = {k: v for k, v in own.items() if k != "kept"}
    rep["kept_rows"] = own["kept"]
    rep["framework_sieve_offline_agrees"] = own == fw
    if campaign == "queue":
        rep["bonds_retain_exactly_feasible"] = sorted({w for _, _, w in own["kept"]}) == rep["feasible"]
    return rep

def jsonable(v):
    if isinstance(v, dict):
        return {(k if isinstance(k, str) else str(k)): jsonable(x) for k, x in v.items()}
    if isinstance(v, (list, tuple, set)):
        return [jsonable(x) for x in v]
    return v

class Report:
    def __init__(self):
        self.checks = []

    def check(self, name, ok, detail=None):
        self.checks.append({"check": name, "passed": bool(ok), "detail": jsonable(detail)})

    @property
    def ok(self):
        return all(c["passed"] for c in self.checks)

def rank_vectors():
    """Ordered set partitions of four records: surjections onto levels 0..k-1, for k = 1..4."""
    by_k = {}
    for k in range(1, 5):
        by_k[k] = sorted(r for r in itertools.product(range(k), repeat=4) if len(set(r)) == k)
    return sorted(r for v in by_k.values() for r in v), {k: len(v) for k, v in by_k.items()}

def key(policy, ranks, direction, request, i):
    s = 1 if direction == "asc" else -1
    return (s * ranks[i],) if policy == "score_only_cursor" else (s * ranks[i], -i if policy == "alternating_ties" and request % 2 else i)

def model(policy, ranks, direction):
    pages, got, cursor = [], [], None
    for request in range(3):
        k = {i: key(policy, ranks, direction, request, i) for i in range(4)}
        order = sorted(range(4), key=lambda i: k[i])                   # keys are distinct except score-only ties
        matrix = [[(k[i] > k[j]) - (k[i] < k[j]) for j in range(4)] for i in range(4)]
        if policy == "alternating_ties":
            chosen, out, offset = order[2 * request: 2 * request + 2], None, 2 * request
        else:
            chosen = [i for i in order if cursor is None or k[i] > tuple(cursor)][:2]
            out, offset = (list(k[chosen[-1]]) if chosen else None), None
        pages.append({"request": request, "cursor_in": cursor, "offset": offset, "full_order": [IDS[i] for i in order],
                      "comparisons": matrix, "ids": [IDS[i] for i in chosen], "cursor_out": out})
        got += [IDS[i] for i in chosen]
        if not chosen:
            break
        cursor = out
    s = 1 if direction == "asc" else -1
    expected = [IDS[i] for i in sorted(range(4), key=lambda i: (s * ranks[i], i))]
    rk = {IDS[i]: ranks[i] for i in range(4)}
    adj = list(zip(got, got[1:]))
    obl = {"multiset_ok": Counter(got) == Counter(IDS),
           "primary_order_ok": all(s * rk[a] <= s * rk[b] for a, b in adj),
           "stable_ties_ok": all(IDS.index(a) <= IDS.index(b) for a, b in adj if rk[a] == rk[b]),
           "terminated": not pages[-1]["ids"]}
    laws = [laws_of(p["comparisons"], ranks, s) for p in pages]
    lawful = all(all(x.values()) for x in laws)
    verdict = "PASS" if got == expected and all(obl.values()) and lawful else "DOMAIN_FAIL"
    return {"pages": pages, "collected": got, "expected": expected, **obl, "comparator_laws": laws, "comparators_lawful": lawful,
            "verdict": verdict}

def laws_of(m, ranks, s):
    ix = range(4)
    return {"signs_ok": all(m[i][j] in (-1, 0, 1) for i in ix for j in ix),
            "reflexive": all(m[i][i] == 0 for i in ix),
            "antisymmetric": all(m[i][j] + m[j][i] == 0 for i in ix for j in ix),
            "transitive_le": not any(m[i][j] <= 0 and m[j][k] <= 0 and m[i][k] > 0 for i, j, k in itertools.product(ix, repeat=3)),
            "primary_direction": all((m[i][j] > 0) == (s * ranks[i] > s * ranks[j]) for i in ix for j in ix if ranks[i] != ranks[j])}

def read_candidates(p):
    with tarfile.open(fileobj=io.BytesIO(gzip.decompress(p.read_bytes()))) as tar:
        return {Path(m.name).name: tar.extractfile(m).read() for m in tar.getmembers()}

def calls_of(src):
    calls, sources = [], None
    for node in ast.parse(src).body:
        if isinstance(node, ast.Expr) and isinstance(node.value, ast.Call) and isinstance(node.value.func, ast.Name):
            calls.append([node.value.func.id, *[ast.literal_eval(a) for a in node.value.args]])
        elif isinstance(node, ast.Assign) and isinstance(node.targets[0], ast.Name) and node.targets[0].id == "_D8_SOURCES":
            sources = ast.literal_eval(node.value)
    return calls, sources

def case_of(calls):
    if [c[0] for c in calls] != ["impl", "ranks", "direction"]:
        raise ValueError(f"atom order {[c[0] for c in calls]}")
    return f"{calls[0][1]}|D={calls[2][1]}|R={calls[1][1]}"

def expected_ids():
    return sorted(f"P={p}|O={''.join(o)}|N={n}|F={f}|X={x}" for p in POLICIES for o in itertools.permutations("ARS")
                  for n in (1, 2) for f in (0, 1) for x in ("none", "0", "1", "2", "3"))

def load(run):
    rows = {}
    for line in (run / "observations.jsonl").read_text().splitlines():
        if not line.strip():
            continue
        r = json.loads(line)
        if not ID_RE.fullmatch(r.get("case_id", "")):
            raise AnalysisInputError(f"unknown identity {r.get('case_id')!r}")
        if r["case_id"] in rows:
            raise AnalysisInputError(f"duplicate {r['case_id']}")
        rows[r["case_id"]] = r
    if sorted(rows) != expected_ids():
        raise AnalysisInputError(f"{len(set(expected_ids()) - set(rows))} identities missing")
    return rows

def analyse(rows):
    def tally(key):
        out = {}
        for r in rows.values():
            out.setdefault(key(r), Counter())[r["verdict"]] += 1
        return {str(k): dict(v) for k, v in sorted(out.items(), key=lambda kv: str(kv[0]))}
    return {"schema": "d13a.analysis/v1", "source": "observed traces of all 480 cases",
            "by_policy": tally(lambda r: r["policy"]),
            "by_policy_repetitions": tally(lambda r: (r["policy"], r["send_repetitions"])),
            "by_policy_read_failure": tally(lambda r: (r["policy"], r["fail_read"])),
            "by_policy_revoke_cut": tally(lambda r: (r["policy"], "none" if r["revoke_cut"] is None else r["revoke_cut"])),
            "by_policy_order": tally(lambda r: (r["policy"], r["order"])),
            "violation_kinds": {p: dict(Counter(v["kind"] for r in rows.values() if r["policy"] == p for v in r["violations"])) for p in POLICIES},
            "counts": {"framework_attempts": len(rows), "send_requests": sum(len(r["send_results"]) for r in rows.values()),
                       "outbox_effects": sum(len(r["outbox"]) for r in rows.values()),
                       "emit_responses": sum(1 for r in rows.values() for s in r["send_results"] if s["action"] == "emit")},
            "timelines": {w: timeline(rows[w]) for w in WITNESSES}}

def fail(msg: str, code: int = 2):
    print(f"run_demo: REFUSED — {msg}", file=sys.stderr)
    raise SystemExit(code)

def pg_connect(port: int, database: str):
    import pg8000.dbapi
    role = "RESULTS" if port == PORTS["results"] else "MAIN"      # credentials come from the Framework's env (bundle_env.sh)
    return pg8000.dbapi.connect(host=os.environ.get(f"BUNDLE_{role}_DB_HOST", "127.0.0.1"), port=port,
                                user=os.environ.get(f"BUNDLE_{role}_DB_USER", "postgres"),
                                password=os.environ[f"BUNDLE_{role}_DB_PASSWORD"], database=database)

def jsonable(v):
    if isinstance(v, (datetime.datetime, datetime.date)):
        return v.isoformat()
    if isinstance(v, (bytes, bytearray, memoryview)):
        return base64.b64encode(bytes(v)).decode("ascii")
    if isinstance(v, (list, tuple)):
        return [jsonable(x) for x in v]
    return v

def run_checked(cmd, **kw):
    r = subprocess.run(cmd, capture_output=True, text=True, **kw)
    return r.returncode, (r.stdout + r.stderr)

def resolve_input():
    sys.path.insert(0, str(GEN))
    import fwgen as fg
    xlsx, toml = fg.load_spec(HERE / "spec" / "demo.xlsx"), fg.load_spec(HERE / "spec" / "spec.toml")
    ids = [c["id"] for c in xlsx.constraints]
    if ids != RULES or xlsx.constraints != toml.constraints or xlsx.params != toml.params:
        fail(f"XLSX companion and TOML do not carry the same three bonds and params: {ids}", code=3)
    if xlsx.sidecar_path != str((HERE / "spec" / "demo.constraints.json").resolve()):
        fail(f"demo.xlsx took its rules from {xlsx.sidecar_path!r}", code=3)
    return HERE / "spec" / "demo.xlsx", ids, {"path": xlsx.sidecar_path, "sha256": xlsx.sidecar_sha256}

def normal_graph(graph):
    """Nodes and edges with each brace node renamed after the sheet it produces (ids differ by input)."""
    name = {e["dst"]: "brace->" + e["src"] for e in graph["edges"] if e["kind"] == "produces"}
    def node(n):
        attrs = dict(n.get("attrs") or {})
        if attrs.get("is_join_result"):
            attrs.pop("verb", None)        # TOML shows the slot's placeholder verb, XLSX the effective brace
        return json.dumps(dict(n, id=name.get(n["id"], n["id"]), attrs=attrs), sort_keys=True)
    nodes = sorted(node(n) for n in graph["nodes"])
    edges = sorted((name.get(e["src"], e["src"]), e["kind"], name.get(e["dst"], e["dst"])) for e in graph["edges"])
    return {"nodes": nodes, "edges": edges}

def plans(dest: Path):
    """Plan both inputs under the campaign budgets."""
    dest.mkdir(parents=True, exist_ok=True)
    env = dict(os.environ, BUNDLE_BUDGET_MANDATORY_ROWS=BUDGETS[1], BUNDLE_BUDGET_FINAL_CANDIDATES=BUDGETS[3],
               BUNDLE_BUDGET_DISK_BYTES=BUDGETS[5], BUNDLE_BUDGET_WALL_TIME_SECONDS=BUDGETS[7])
    out = {}
    for kind, name in (("toml", "spec.toml"), ("xlsx", "demo.xlsx")):
        r = subprocess.run([sys.executable, str(GEN / "bundle_run.py"), "plan", str(HERE / "spec" / name),
                            "--out", str(dest / f"plan-{kind}")], cwd=REPO, env=env, capture_output=True, text=True)
        (dest / f"plan-{kind}.log").write_text(r.stdout + r.stderr, encoding="utf-8")
        if r.returncode != 0:
            fail(f"plan of {name} failed")
        out[kind] = json.loads((dest / f"plan-{kind}" / "plan.json").read_text(encoding="utf-8"))
        r = subprocess.run([sys.executable, str(GEN / "bundle_run.py"), "constraints", "explain",
                            str(HERE / "spec" / name)], cwd=REPO, capture_output=True, text=True)
        (dest / f"constraints-explain-{kind}.log").write_text(r.stdout + r.stderr, encoding="utf-8")
        if r.returncode != 0 or not all(rule in r.stdout for rule in RULES):
            fail(f"constraints explain of {name} does not list the three bonds")
    card = {k: {c: [p["cardinality"][c]["mode"], p["cardinality"][c]["value"], p["cardinality"][c].get("lower"),
                    p["cardinality"][c].get("upper")] for c in ("mandatory", "post_sieve", "optional_multiplier", "final")}
            for k, p in out.items()}
    reasons = {k: {c: p["cardinality"][c].get("reasons") for c in ("mandatory", "post_sieve", "final")} for k, p in out.items()}
    per_slot = {k: p["cardinality"]["per_slot"] for k, p in out.items()}
    graph = {k: p["dependency_graph"].get("sha256") or hashlib.sha256(json.dumps(p["dependency_graph"]["graph"],
             sort_keys=True).encode()).hexdigest() for k, p in out.items()}
    g = {k: p["dependency_graph"]["graph"] for k, p in out.items()}
    summary = {"cardinality": card, "per_slot": per_slot, "constraints_present": {k: p["constraints_present"] for k, p in out.items()},
               "budget_blocking": {k: p["budget_blocking"] for k, p in out.items()},
               "dependency_graph_sha256": graph, "same_dependency_graph": graph["toml"] == graph["xlsx"],
               "normal_graph": {k: normal_graph(v) for k, v in g.items()}, "reasons": reasons,
               "warnings": {k: p.get("warnings") for k, p in out.items()},
               "note": ("post-sieve and final BOUNDED [0, 288] is the planner's sound bound: it does not evaluate these "
                        "predicates' selectivity. Recorded, not overridden; the independent model predicts 54.")}
    for k in ("toml", "xlsx"):
        c = card[k]
        if c["mandatory"][:2] != ["EXACT", RAW] or c["final"][3] is None or c["final"][3] > 350 \
                or not (c["final"][2] or 0) <= EXPECTED <= c["final"][3] or out[k]["constraints_present"] != 3 or out[k]["budget_blocking"]:
            fail(f"{k} plan is outside the contract: {c} blocking={out[k]['budget_blocking']}")
    summary["same_normal_graph"] = summary["normal_graph"]["toml"] == summary["normal_graph"]["xlsx"]
    if card["toml"] != card["xlsx"] or not summary["same_normal_graph"]:
        fail(f"the TOML and XLSX plans describe different programs: {summary['normal_graph']}")
    (dest / "plan-comparison.json").write_text(json.dumps(summary, indent=2) + "\n", encoding="utf-8")
    return summary

def bundle_command(input_path: Path, db: str, run_id: str, runs_root: Path):
    return [sys.executable, str(GEN / "bundle_run.py"), str(input_path), "--db", db, "--lang", "py", "--sieve",
            "--run-id", run_id, "--runs-root", str(runs_root), *BUDGETS,
            "--execution-policy-profile", "generated-default", "--candidate-origin", "generated",
            "--executor-workers", "1", "--repeat", "1"]

