def parse_args(argv: list[str] | None = None) -> tuple[Path, list[str]]:
    values = list(sys.argv[1:] if argv is None else argv)
    try:
        divider = values.index("--")
    except ValueError as exc:
        raise SystemExit("workbook_runner requires '--' before bundle arguments") from exc
    parser = argparse.ArgumentParser(description="Run Bundle using an existing validated Core workbook")
    parser.add_argument("--workbook", required=True, type=Path)
    own = parser.parse_args(values[:divider])
    bundle_args = values[divider + 1:]
    if not bundle_args:
        raise SystemExit("no Bundle arguments supplied after '--'")
    return own.workbook, bundle_args

def _expand(verb, opts):
    if verb == "FW_Combi(1)":
        return [(l, t) for l, t in opts]
    if verb == "FW_Subsets":
        out = []
        for r in range(len(opts) + 1):
            for c in itertools.combinations(opts, r):
                out.append(("+".join(l for l, _ in c) or "none", "".join(t for _, t in c)))
        return out
    if verb == "FW_Permut":
        return [(">".join(l for l, _ in p), "".join(t for _, t in p))
                for p in itertools.permutations(opts)]
    raise SystemExit(f"unhandled verb {verb}")

def reassemble(matrix=MATRIX):
    keys = [s for s, _, _ in matrix]
    per = [_expand(v, o) for _, v, o in matrix]
    for idx, combo in enumerate(itertools.product(*per)):
        labels = {keys[i].lower(): combo[i][0] for i in range(len(combo))}
        text = "".join(c[1] for c in combo)
        yield idx, labels, text

def count(matrix=MATRIX):
    n = 1
    for _, v, o in matrix:
        n *= len(_expand(v, o))
    return n

