    DISPLAY_NAME: ClassVar[str]
    CATEGORY: ClassVar[str] = "Other"
    DESCRIPTION: ClassVar[str] = ""
    INPUTS: ClassVar[tuple[PortSpec, ...]] = ()
    OUTPUTS: ClassVar[tuple[PortSpec, ...]] = ()
    PARAMETERS: ClassVar[tuple[ParameterSpec, ...]] = ()
    MEASUREMENTS: ClassVar[tuple[MeasurementSpec, ...]] = ()
    BREAKS_CYCLE: ClassVar[bool] = False
    TAGS: ClassVar[tuple[str, ...]] = ()

    def __init__(self, parameters: Mapping[str, Any] | None = None) -> None:
        self._initialized = False
        self._parameters = self.descriptor().defaults()
        self._outputs: dict[str, SignalValue] = {
            port.name: port.default for port in self.OUTPUTS
        }
        self._last_inputs: dict[str, SignalValue] = {
            port.name: port.default for port in self.INPUTS
        }
        self._last_context = StepContext(time=0.0, dt=0.0, tick=0)
        self._measurements: dict[str, SignalValue] = {}
        if parameters:
            self.set_parameters(parameters)
        self.reset()
        self._initialized = True
        self._refresh_measurements(
            self._last_inputs, self._outputs, self._last_context
        )

    @classmethod
    def descriptor(cls) -> ComponentDescriptor:
        return ComponentDescriptor(
            type_id=cls.TYPE_ID,
            display_name=cls.DISPLAY_NAME,
            category=cls.CATEGORY,
            description=cls.DESCRIPTION,
            inputs=cls.INPUTS,
            outputs=cls.OUTPUTS,
            parameters=cls.PARAMETERS,
            measurements=cls.measurement_specs(),
            breaks_cycle=cls.BREAKS_CYCLE,
            tags=cls.TAGS,
        )

    @classmethod
    def measurement_specs(cls) -> tuple[MeasurementSpec, ...]:
        specs: list[MeasurementSpec] = []
        for port in cls.INPUTS:
            specs.append(
                MeasurementSpec(
                    f"input.{port.name}",
                    MeasurementRole.TERMINAL_INPUT,
                    kind=port.kind,
                    default=port.default,
                    unit=port.unit,
                    description=f"Value sampled at input terminal '{port.name}'.",
                )
            )
        for port in cls.OUTPUTS:
            specs.append(
                MeasurementSpec(
                    f"output.{port.name}",
                    MeasurementRole.TERMINAL_OUTPUT,
                    kind=port.kind,
                    default=port.default,
                    unit=port.unit,
                    description=f"Newly committed value at output terminal '{port.name}'.",
                )
            )
            specs.append(
                MeasurementSpec(
                    f"presented.{port.name}",
                    MeasurementRole.PRESENTED_OUTPUT,
                    kind=port.kind,
                    default=port.default,
                    unit=port.unit,
                    description=(
                        f"Value from '{port.name}' presented to downstream blocks "
                        "during this simulation tick."
                    ),
                )
            )
        for parameter in cls.PARAMETERS:
            if parameter.kind not in {
                ParameterKind.NUMBER,
                ParameterKind.INTEGER,
                ParameterKind.BOOLEAN,
            }:
                continue
            kind = (
                SignalKind.BOOLEAN
                if parameter.kind is ParameterKind.BOOLEAN
                else SignalKind.SCALAR
            )
            specs.append(
                MeasurementSpec(
                    f"parameter.{parameter.name}",
                    MeasurementRole.PARAMETER,
                    kind=kind,
                    default=parameter.default,
                    unit=parameter.unit,
                    description=(
                        parameter.description
                        or f"Current configured value of '{parameter.name}'."
                    ),
                )
            )
        specs.extend(cls.MEASUREMENTS)
        names = [spec.name for spec in specs]
        if len(names) != len(set(names)):
            raise ValueError(f"Duplicate measurement names on '{cls.TYPE_ID}'")
        return tuple(specs)

    @property
    def parameters(self) -> dict[str, Any]:
        return dict(self._parameters)

    @property
    def outputs(self) -> dict[str, SignalValue]:
        return dict(self._outputs)

    @property
    def measurements(self) -> dict[str, SignalValue]:
        return dict(self._measurements)

    def parameter(self, name: str) -> Any:
        if name not in self._parameters:
            raise ValidationError(f"Unknown parameter '{name}' for '{self.TYPE_ID}'")
        return self._parameters[name]

    def set_parameters(self, updates: Mapping[str, Any]) -> None:
        """Validate all changes before committing any of them."""
        descriptor = self.descriptor()
        candidate = dict(self._parameters)
        for name, raw_value in updates.items():
            candidate[name] = descriptor.parameter(name).coerce(raw_value)
        self.validate_parameter_set(candidate)
        self._parameters = candidate
        self.on_parameters_changed()
        if self._initialized:
            self._refresh_measurements(
                self._last_inputs, self._outputs, self._last_context
            )

    def validate_parameter_set(self, parameters: Mapping[str, Any]) -> None:
        """Hook for relationships such as min <= max."""

    def on_parameters_changed(self) -> None:
        """Hook for rebuilding cached state after a valid parameter change."""

    def reset(self) -> None:
        self._outputs = {port.name: port.default for port in self.OUTPUTS}

    def reset_runtime(self) -> None:
        """Reset implementation state and all independent tester terminals."""
        self.reset()
        self._last_inputs = {port.name: port.default for port in self.INPUTS}
        self._last_context = StepContext(time=0.0, dt=0.0, tick=0)
        self._refresh_measurements(
            self._last_inputs, self._outputs, self._last_context
        )

    def preview(self, context: StepContext) -> Mapping[str, SignalValue]:
        """Outputs made visible before a state-boundary component advances."""
        return self._outputs

    def execute(
        self, inputs: Mapping[str, SignalValue], context: StepContext
    ) -> dict[str, SignalValue]:
        raw = self.process(inputs, context)
        self._outputs = self._validate_outputs(raw)
        self._last_inputs = dict(inputs)
        self._last_context = context
        self._refresh_measurements(inputs, self._outputs, context)
        return dict(self._outputs)

    @abstractmethod
    def process(
        self, inputs: Mapping[str, SignalValue], context: StepContext
    ) -> Mapping[str, SignalValue]:
        """Calculate the next outputs from typed inputs."""

    def export_state(self) -> dict[str, Any]:
        """Optional runtime state for diagnostics; projects store design only."""
        return {}

    def import_state(self, state: Mapping[str, Any]) -> None:
        """Restore compatible runtime state when a host explicitly requests it."""
        if state:
            raise ValidationError(f"'{self.TYPE_ID}' does not accept runtime state")

    def measure_internal(
        self,
        inputs: Mapping[str, SignalValue],
        outputs: Mapping[str, SignalValue],
        context: StepContext,
    ) -> Mapping[str, SignalValue]:
        """Return values for component-specific ``MEASUREMENTS`` terminals."""
        return {}

    def _validate_outputs(
        self, outputs: Mapping[str, SignalValue]
    ) -> dict[str, SignalValue]:
        expected = {port.name: port for port in self.OUTPUTS}
        missing = expected.keys() - outputs.keys()
        extra = outputs.keys() - expected.keys()
        if missing or extra:
            raise ValidationError(
                f"'{self.TYPE_ID}' returned an invalid output set; "
                f"missing={sorted(missing)}, extra={sorted(extra)}"
            )

        result: dict[str, SignalValue] = {}
        for name, value in outputs.items():
            port = expected[name]
            if port.kind is SignalKind.BOOLEAN:
                result[name] = bool(value)
            elif port.kind is SignalKind.ANY and isinstance(value, bool):
                result[name] = value
            else:
                number = float(value)
                if not math.isfinite(number):
                    raise ValidationError(
                        f"'{self.TYPE_ID}.{name}' produced a non-finite value"
                    )
                result[name] = number
        return result

    def _refresh_measurements(
        self,
        inputs: Mapping[str, SignalValue],
        outputs: Mapping[str, SignalValue],
        context: StepContext,
    ) -> None:
        values: dict[str, SignalValue] = {}
        for port in self.INPUTS:
            values[f"input.{port.name}"] = inputs.get(port.name, port.default)
        for port in self.OUTPUTS:
            output = outputs.get(port.name, port.default)
            values[f"output.{port.name}"] = output
            values[f"presented.{port.name}"] = output
        for parameter in self.PARAMETERS:
            if parameter.kind in {
                ParameterKind.NUMBER,
                ParameterKind.INTEGER,
                ParameterKind.BOOLEAN,
            }:
                values[f"parameter.{parameter.name}"] = self._parameters[
                    parameter.name
                ]
        custom = self.measure_internal(inputs, outputs, context)
        custom_names = {spec.name for spec in self.MEASUREMENTS}
        extra = set(custom) - custom_names
        if extra:
            raise ValidationError(
                f"'{self.TYPE_ID}' returned undeclared measurements: "
                f"{sorted(extra)}"
            )
        for spec in self.MEASUREMENTS:
            values[spec.name] = custom.get(spec.name, spec.default)

        expected = {spec.name: spec for spec in self.measurement_specs()}
        self._measurements = {
            name: self._coerce_measurement(expected[name], value)
            for name, value in values.items()
        }

    @staticmethod
    def _coerce_measurement(
        spec: MeasurementSpec, value: SignalValue
    ) -> SignalValue:
        if spec.kind is SignalKind.BOOLEAN:
            return bool(value)
        if spec.kind is SignalKind.ANY and isinstance(value, bool):
            return value
        number = float(value)
        if not math.isfinite(number):
            raise ValidationError(
                f"Measurement terminal '{spec.name}' produced a non-finite value"
            )
        return number
