"""Policy contracts shared by clearing, risk and the interbank network.

These are deliberately tiny, dependency-light protocols so the transfer state
machine in :mod:`clearing` never imports a concrete gate or executor — banks
wire the implementations in. That is what lets the *same* state machine run an
intra-bank settlement or a cross-bank one just by swapping the executor, and
add/remove sanctions or risk checks just by changing the gate list.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from enum import Enum
from typing import Protocol, runtime_checkable

from .kernel import Money


class GateDecision(str, Enum):
    ALLOW = "ALLOW"
    REVIEW = "REVIEW"  # let it proceed, but a human must approve before settlement
    BLOCK = "BLOCK"  # hard stop, terminal

    @property
    def severity(self) -> int:
        return {"ALLOW": 0, "REVIEW": 1, "BLOCK": 2}[self.value]


@dataclass(frozen=True)
class TransferContext:
    """The facts a gate or executor needs about one transfer."""

    reference: str
    amount: Money
    source_client_id: str
    target_client_id: str
    source_account_id: str
    target_account_id: str
    source_bank: str
    target_bank: str

    @property
    def cross_bank(self) -> bool:
        return self.source_bank != self.target_bank


@dataclass(frozen=True)
class GateResult:
    gate: str
    decision: GateDecision
    reasons: tuple[str, ...] = ()
    metadata: dict = field(default_factory=dict)

    def view(self) -> dict:
        return {
            "gate": self.gate,
            "decision": self.decision.value,
            "reasons": list(self.reasons),
            "metadata": self.metadata,
        }


@runtime_checkable
class PolicyGate(Protocol):
    name: str

    def evaluate(self, ctx: TransferContext) -> GateResult: ...


@runtime_checkable
class SettlementExecutor(Protocol):
    """Moves the money once a transfer is fully authorized."""

    def place_hold(self, ctx: TransferContext) -> None: ...

    def settle(self, ctx: TransferContext) -> dict: ...

    def release(self, ctx: TransferContext) -> None: ...


def combine(results: list[GateResult]) -> GateDecision:
    worst = GateDecision.ALLOW
    for r in results:
        if r.decision.severity > worst.severity:
            worst = r.decision
    return worst

