class FlexibleMoE(nn.Module):
    """Dynamic MoE layer that balances parameter count up to 20GB limits."""
    def __init__(self, d_model: int, d_ffn: int, num_experts: int = 16):
        super().__init__()
        if min(d_model, d_ffn) <= 0:
            raise ValueError("d_model and d_ffn must be positive")
        if num_experts < 2:
            raise ValueError("num_experts must be at least 2")

        self.router = nn.Linear(d_model, num_experts, bias=False)
        self.experts = nn.ModuleList([
            nn.Sequential(BitLinear(d_model, d_ffn), nn.SiLU(), BitLinear(d_ffn, d_model))
            for _ in range(num_experts)
        ])

    def forward(self, x):
        B, S, D = x.shape
        x_flat = x.reshape(-1, D)
        gates = F.softmax(self.router(x_flat), dim=-1)
        weights, selected = torch.topk(gates, 2, dim=-1)
        weights /= weights.sum(dim=-1, keepdim=True)

        out = torch.zeros_like(x_flat)
        for i, expert in enumerate(self.experts):
            mask = (selected == i).any(dim=-1)
            if mask.any():
                idx = (selected[mask] == i).nonzero(as_tuple=True)[1]
                out[mask] += expert(x_flat[mask]) * weights[mask, idx].unsqueeze(-1)
        return out.reshape(B, S, D)

# ==========================================
# 3. GRAPH ENGINE COORDINATOR
# ==========================================

class AgileParallelEngine:
    def __init__(self, config):
        self.config = dict(config)
        required = {"d_model", "d_ffn", "n_heads", "num_experts"}
        missing = required.difference(self.config)
        if missing:
            raise ValueError(f"missing engine configuration keys: {sorted(missing)}")
        if min(self.config[key] for key in required) <= 0:
            raise ValueError("engine dimensions, head count, and expert count must be positive")
        if self.config["d_model"] % self.config["n_heads"] != 0:
            raise ValueError("d_model must be divisible by n_heads")
        if self.config["num_experts"] < 2:
            raise ValueError("num_experts must be at least 2")

        # Build flexible routing channels
        self.communication_bus = {
            0: mp.Queue(), # Route to Module 0
            1: mp.Queue(), # Route to Module 1
            2: mp.Queue(), # Route to Module 2
            3: mp.Queue(), # Route to Module 3
            "terminal": mp.Queue()
        }

        self.workers = []
        self._provision_hardware_pool()

    def _provision_hardware_pool(self):
        try:
            available_cores = psutil.Process().cpu_affinity()
        except (AttributeError, NotImplementedError):
            available_cores = list(range(os.cpu_count() or 1))
        if not available_cores:
            raise RuntimeError("no CPU cores are available for worker affinity")

        selected_cores = available_cores[:min(8, len(available_cores))]
        if len(selected_cores) >= 4:
            base, remainder = divmod(len(selected_cores), 4)
            groups = []
            offset = 0
            for index in range(4):
                size = base + (1 if index < remainder else 0)
                groups.append(selected_cores[offset:offset + size])
                offset += size
        else:
            groups = [[selected_cores[index % len(selected_cores)]] for index in range(4)]

        module_types = ["attention", "moe", "attention", "moe"]
        topology = {
            index: {"cores": groups[index], "type": module_types[index]}
            for index in range(4)
        }

        for mod_id, hardware in topology.items():
            p = mp.Process(
                target=agile_worker_loop,
                args=(
                    mod_id,
                    hardware["cores"],
                    self.communication_bus[mod_id],
                    self.communication_bus,
                    hardware["type"],
                    self.config
                )
            )
            self.workers.append(p)
            p.start()

    def execute_graph_async(self, input_embeddings, custom_route):
        """Streams a raw input tensor into the runtime execution graph."""
        if input_embeddings.ndim != 3:
            raise ValueError("input_embeddings must have shape [batch, sequence, d_model]")
        if input_embeddings.shape[-1] != self.config["d_model"]:
            raise ValueError("input embedding width must match config d_model")

        route = list(custom_route)
        valid_stages = {0, 1, 2, 3}
        if not route:
            raise ValueError("custom_route must contain at least one stage")
        if any(stage not in valid_stages for stage in route):
            raise ValueError("custom_route contains an unknown stage")

        task_id = time.time_ns()
        shared_tensor = input_embeddings.clone().share_memory_()
        packet = TaskPacket(task_id, shared_tensor, route)
        first_hop = packet.next_stage()
        self.communication_bus[first_hop].put(packet)
        return task_id

    def shutdown(self):
        if not self.workers:
            return
        for mod_id in [0, 1, 2, 3]:
            self.communication_bus[mod_id].put(None)
        for worker in self.workers:
            worker.join(timeout=10)
            if worker.is_alive():
                worker.terminate()
                worker.join()
        self.workers.clear()
        print("[ENGINE] All agile worker pipelines successfully unmounted.")
